public class Student {
    private static int studentCount = 0;    // shared by every Student
    private String name;                    // one per object

    public Student(String name) {
        this.name = name;
        studentCount++;                     // every construction increments the shared counter
    }

    public String getName() { return name; }

    public static int getStudentCount() {   // static: called on the class
        return studentCount;
        // return name;   // error, which object's name would that be?
    }
}

public class EnrollmentDemo {
    public static void main(String[] args) {
        System.out.println(Student.getStudentCount());   // 0, no objects yet

        Student a = new Student("Ana");
        Student b = new Student("Jess");
        Student c = new Student("Marie");

        System.out.println(a.getName());                 // Ana
        System.out.println(Student.getStudentCount());   // 3
    }
}
